// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // Which Google Calendar to use. 'primary' = your main calendar
    calendar_id: "primary",
    // Your time zone, e.g. America/New_York, America/Chicago, America/Los_Angeles
    timezone: "America/New_York",
    // Length of a strategy call in minutes
    call_minutes: 30,
  },
}];

const req = $('Vapi Tool Call').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};
const toolCall =
  (msg.toolCallList ?? msg.toolCalls ?? [])[0] ??
  msg.toolWithToolCallList?.[0]?.toolCall ?? {};
let args = toolCall.function?.arguments ?? toolCall.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { args = {}; }
}
const toolCallId = toolCall.id ?? '';

const cfg = $('Config').first().json;
const start = DateTime.fromISO(String(args.start_time ?? ''), { setZone: true });
const minutes = Number(args.duration_minutes) || Number(cfg.call_minutes) || 30;
const valid = start.isValid && start > DateTime.now();
const end = valid ? start.plus({ minutes }) : null;
return [{
  json: {
    tool_call_id: toolCallId,
    valid,
    time_min: valid ? start.toISO() : DateTime.now().toISO(),
    time_max: valid ? end.toISO() : DateTime.now().plus({ minutes: 1 }).toISO(),
    event: {
      summary: `IntakeOps strategy call – ${args.caller_name || 'New lead'}` +
        (args.business_name ? ` (${args.business_name})` : ''),
      description: [
        `Name: ${args.caller_name || 'Unknown'}`,
        `Phone: ${args.caller_phone || call.customer?.number || msg.customer?.number || 'Unknown'}`,
        `Business: ${args.business_name || 'Unknown'}`,
        args.notes ? `Notes: ${args.notes}` : '',
        'Booked by Billy (IntakeOps AI receptionist).',
      ].filter(Boolean).join('\n'),
      start: { dateTime: valid ? start.toISO() : null, timeZone: cfg.timezone },
      end: { dateTime: valid ? end.toISO() : null, timeZone: cfg.timezone },
    },
    spoken_time: valid ? start.setZone(cfg.timezone).toFormat("cccc, LLLL d 'at' h:mm a") : '',
  },
}];

const cfg = $('Config').first().json;
const req = $('Parse Tool Call').first().json;
const fb = $input.first().json;
const calId = cfg.calendar_id;
const cal = fb.calendars?.[calId] ?? Object.values(fb.calendars ?? {})[0];
const calendarOk = Boolean(cal) && !fb.error && !(cal.errors?.length);
const busy = (cal?.busy ?? []).map((b) => [DateTime.fromISO(b.start), DateTime.fromISO(b.end)]);
const overlaps = (s, e) => busy.some(([bs, be]) => s < be && e > bs);

let book = false;
let result;
if (!req.valid) {
  result = 'That time is missing or in the past. Call checkCalendar again and offer one of the open times.';
} else if (!calendarOk) {
  result = "The calendar couldn't be reached. Tell the caller the team will call today to confirm the time.";
} else if (overlaps(DateTime.fromISO(req.time_min), DateTime.fromISO(req.time_max))) {
  result = 'That time was just taken. Call checkCalendar again and offer the next open times.';
} else {
  book = true;
}
return [{ json: { tool_call_id: req.tool_call_id, book, result: result ?? '' } }];

const req = $('Parse Tool Call').first().json;
const created = $input.first().json;
const result = created.id
  ? `Booked for ${req.spoken_time}. Confirm the time with the caller and tell them they'll get a text.`
  : "Booking didn't go through. Tell the caller the team will call today to confirm the time.";
return [{ json: { tool_call_id: req.tool_call_id, result } }];
